import { isPageError } from "../shared/pageClient";
import { LINK_CLOSED } from "../shared/pageStreams";

/**
 * Auth is a read, so a lost bridge can be retried even when an older host omits retryable.
 * Keep every code generated by BridgePageClient, PageError and PageProviders explicit here.
 * Owner errors forwarded by the bridge are not evidence of a lost link (even if retryable).
 */
export function connectionFailure(error: unknown): "disconnected" | "failed" {
  if (!isPageError(error)) return "failed";
  switch (error.code) {
    case LINK_CLOSED:
    case "cmux.protocol.transport":
    case "cmux.protocol.timeout":
    case "cmux.protocol.unavailable":
      return "disconnected";
    case "cmux.op.cancelled":
    case "cmux.page.cancelled":
    case "cmux.page.not_parked":
    case "cmux.page.failed":
    case "cmux.protocol.error":
    case "cmux.protocol.invalid_result":
    case "cmux.protocol.unknown_op":
    case "cmux.protocol.invalid_params":
    case "cmux.protocol.bad_message":
    case "cmux.daemon.failed":
    case "cmux.policy.turned_off":
      return "failed";
    default:
      // The wire permits arbitrary owner error codes: retain the error and manual Retry.
      // Never replay a failed owner operation just because its retryable flag is true.
      return "failed";
  }
}
